class Solution {
    private Node first = null;
    private Node last = null;

    private void inorder(Node node) {
        if (node == null) return;
        inorder(node.left);
        if (last != null) {
            last.right = node;
            node.left = last;
        } else {
            first = node;
        }
        last = node;
        inorder(node.right);
    }

    public Node treeToDoublyList(Node root) {
        if (root == null) return null;
        inorder(root);
        last.right = first;
        first.left = last;
        return first;
    }
}

