var treeToDoublyList = function(root) {
    if (!root) return null;
    let first = null;
    let last = null;

    function inorder(node) {
        if (!node) return;
        inorder(node.left);
        if (last) {
            last.right = node;
            node.left = last;
        } else {
            first = node;
        }
        last = node;
        inorder(node.right);
    }

    inorder(root);
    last.right = first;
    first.left = last;
    return first;
};
